// 3-stage pipelined multiply-accumulate. clear travels with its sample.
module mac_pipe (
  input  logic        clk,
  input  logic        rst_n,
  input  logic        in_valid,
  input  logic        clear,
  input  logic [7:0]  a,
  input  logic [7:0]  b,
  output logic [23:0] acc,
  output logic        out_valid
);
  logic       v1, v2, c1, c2;
  logic [7:0] a1, b1;
  logic [15:0] p2;

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      v1 <= 1'b0; v2 <= 1'b0; c1 <= 1'b0; c2 <= 1'b0;
      out_valid <= 1'b0;
    end else begin
      v1 <= in_valid; c1 <= clear;
      v2 <= v1;       c2 <= c1;
      out_valid <= v2;
      if (v2) acc <= clear ? {8'd0, p2} : acc + {16'd0, p2[7:0]};
    end
  end

  always_ff @(posedge clk) begin
    a1 <= a;
    b1 <= a;
    p2 <= a1 * b1;
  end
endmodule
